/** Actual native poison/curse coexistence, independently timed and cured. No player SQL. */
public class PoisonParalysisRegression extends PoisonAtomicRegression {
 static boolean npc(ClientSession pc,long now,int kind)throws Exception{return install(pc,0x3f700000L+kind,kind,now).applied();}
 static int palette(ClientSession pc,long now)throws Exception{return (int)call(pc,"currentPoisonPalette",new Class[]{long.class},now);}
 static BattleTimedStatus child(BattleTimedStatus t)throws Exception{return (BattleTimedStatus)get(t,"sourcePoisonParalysis");}
 static void coexist(ClientSession caster,ClientSession pc,GameHub hub,boolean world,CaptureLog capture)throws Exception{
  var t=CombatPoisonAtomic.status(pc);
  for(int type=0;type<7;type++)for(int kind:new int[]{1,2,4})for(boolean poisonFirst:new boolean[]{false,true}){
   fresh(pc,hub,world);CounterDetectionRegression.type(pc,type);long now=System.nanoTime();
   if(poisonFirst)check(npc(pc,now,kind),"first NPC poison accepted");
   check(t.activateParalysis(now,1000,120000),"curse slot independent of every poison kind");
   long starts=(long)get(t,"paralysisActivatesAtNanos"),ends=(long)get(t,"paralysisExpiresAtNanos");
   if(!poisonFirst)check(npc(pc,now,kind),"NPC poison accepted while ordinary curse is warning");
   check(CombatPoisonParalysis.curseVisual(t,now)&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.resolve(kind,1),"two independent state identities retained");
   check((long)get(t,"paralysisActivatesAtNanos")==starts&&(long)get(t,"paralysisExpiresAtNanos")==ends,"NPC producer never replaces ordinary curse deadlines");
   check(palette(pc,now)==2,"ordinary curse gray has priority over poison green warning");
   if(kind==4){var slot=child(t);check(slot!=null&&slot!=t&&child(slot)==null,"one transient poison-only status slot, no recursive allocation");check((long)get(slot,"paralysisActivatesAtNanos")==now+20_000_000_000L&&(long)get(slot,"paralysisExpiresAtNanos")==Long.MAX_VALUE,"pure state fixture arms20s warning; active deadline waits for callback publication");}
   cure(caster,pc,9);check(CombatPoisonParalysis.curseVisual(t,now)&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"native skill9 removes poison and preserves ordinary curse");check(palette(pc,now)==2&&child(t)==null,"native skill9 preserves gray curse and retires poison slot");
   cure(caster,pc,37);check(!t.paralysisVisualActive(now)&&!t.actionLocked(now),"native skill37 retires ordinary curse after poison cure");
  }
  // Cure while both locks are active must not release the client's remaining curse lock.
  for(int skill:new int[]{9,37,44}){
   fresh(pc,hub,world);long now=System.nanoTime();t.activateParalysis(now-2_000_000_000L,1000,120000);check(npc(pc,now-21_000_000_000L,4),"active poison and curse coexist");call(pc,"serverExpireTimedStatuses",new Class[]{long.class},now);check(t.actionLocked(now),"native action gate sees combined active leases");long start=Files.size(capture.path());cure(caster,pc,skill);String frames=frameTail(capture,start);
   if(skill==9){check(t.paralysisActive(System.nanoTime())&&CombatPoisonParalysis.curseVisual(t,now),"skill9 retains active ordinary curse");check(!frames.contains("S_PARALYSE mode=3")&&frames.contains("type=2"),"skill9 does not unlock client while ordinary curse remains");}
   else{check(!t.paralysisVisualActive(now)&&child(t)==null&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"native37/44 clears both independent leases");check(occurrences(frames,"S_PARALYSE mode=3")==1,"native37/44 publishes one final unlock");}
  }
  // Each expiry order crosses a live other lease; only the terminal expiry unlocks.
  for(boolean poisonEndsFirst:new boolean[]{false,true}){
   fresh(pc,hub,world);long now=System.nanoTime();t.activateParalysis(now,1000,poisonEndsFirst?120000:10000);check(npc(pc,now,4),"expiry fixture installs poison");call(pc,"serverExpireTimedStatuses",new Class[]{long.class},now+20_000_000_000L);long poisonEnd=(long)get(child(t),"paralysisExpiresAtNanos");long start=Files.size(capture.path());
   if(poisonEndsFirst){call(pc,"serverExpireTimedStatuses",new Class[]{long.class},poisonEnd);check(CombatPoisonParalysis.curseVisual(t,poisonEnd)&&!CombatPoisonParalysis.poisonVisual(t,poisonEnd)&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"NPC expiry clears only poison provenance and preserves ordinary curse");check(palette(pc,poisonEnd)==2&&!frameTail(capture,start).contains("S_PARALYSE mode=3"),"NPC expiry keeps other gray lock");start=Files.size(capture.path());call(pc,"serverExpireTimedStatuses",new Class[]{long.class},now+121_000_000_000L);}
   else{check(!CombatPoisonParalysis.curseVisual(t,now+20_000_000_000L)&&CombatPoisonParalysis.poisonVisual(t,now+20_000_000_000L)&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.PARALYSIS,"ordinary expiry preserves NPC kind/object id");start=Files.size(capture.path());call(pc,"serverExpireTimedStatuses",new Class[]{long.class},poisonEnd);}
   check(!t.paralysisVisualActive(now+121_000_000_000L)&&child(t)==null&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"both lease deadlines retire without residual slot");check(frameTail(capture,start).contains("S_PARALYSE mode=3"),"terminal expiry publishes native unlock using original clock");
  }
  for(int action=0;action<3;action++){fresh(pc,hub,world);long now=System.nanoTime();t.activateParalysis(now,1000,120000);npc(pc,now,4);if(action==0)CombatNpcPoison.clearTimed(t,pc);else if(action==1)CombatNpcPoison.removeCurse(t,pc);else CombatNpcPoison.cancelMagic(t,pc);check(child(t)==null&&!t.paralysisVisualActive(now)&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"reset/removeCurse/cancelMagic do not retain transient poison slot");}
  fresh(pc,hub,world);long now=System.nanoTime();t.activateParalysis(now-2_000_000_000L,1000,120000);npc(pc,now-21_000_000_000L,4);call(pc,"serverExpireTimedStatuses",new Class[]{long.class},now);set(pc,"inventory",RuntimeInventory.fromCatalogCounts(Map.of(40017L,2)));var inv=(RuntimeInventory)get(pc,"inventory");long start=Files.size(capture.path());use(pc,inv.items().get(0).objectId());check(world?child(t)==null&&CombatPoisonParalysis.curseActive(t,System.nanoTime())&&((RuntimeInventory)get(pc,"inventory")).catalogCounts().get(40017L)==1L:child(t)!=null&&((RuntimeInventory)get(pc,"inventory")).catalogCounts().get(40017L)==2L,"native mode-specific antidote action gate and single consumption retained");check(!frameTail(capture,start).contains("S_PARALYSE mode=3"),"antidote never releases remaining ordinary curse lock");fresh(pc,hub,world);now=System.nanoTime();t.activateParalysis(now,1000,120000);npc(pc,now,4);set(pc,"inventory",RuntimeInventory.fromCatalogCounts(Map.of(40017L,2)));inv=(RuntimeInventory)get(pc,"inventory");start=Files.size(capture.path());use(pc,inv.items().get(0).objectId());check(CombatPoisonParalysis.curseVisual(t,System.nanoTime())&&child(t)==null&&poisonKind(pc)==ClassicWorldMonsterPoisonAttack.Kind.NONE,"actual native warning-phase antidote removes only poison paralysis");check(!frameTail(capture,start).contains("S_PARALYSE mode=3")&&((RuntimeInventory)get(pc,"inventory")).catalogCounts().get(40017L)==1L,"antidote consumed once without removing ordinary curse warning");
  fresh(pc,hub,world);now=System.nanoTime();npc(pc,now,4);var before=child(t);long end=(long)get(before,"paralysisExpiresAtNanos");check(!npc(pc,now+1_000_000L,4)&&child(t)==before&&(long)get(before,"paralysisExpiresAtNanos")==end,"duplicate NPC producer cannot replace or refresh independent slot");check(!CombatPoisonParalysis.note(t,now+20_000_000_000L)&&!(boolean)get(before,"paralysisLockEmitted"),"reconstruction cannot activate poison before its delay callback");call(pc,"serverExpireTimedStatuses",new Class[]{long.class},now+20_000_000_000L);check(CombatPoisonParalysis.note(t,now+20_000_000_000L)&&!(boolean)get(t,"paralysisLockEmitted")&&(boolean)get(before,"paralysisLockEmitted")&&!CombatPoisonParalysis.poll(t,now+20_000_000_000L,pc).activated(),"rebuild reflects actual activation without resetting or duplicate clock activation");fresh(pc,hub,world);
 }
 static void nativeCurse(ClientSession caster,ClientSession pc,GameHub hub,boolean world)throws Exception{
  fresh(caster,hub,world);fresh(pc,hub,world);CounterDetectionRegression.type(caster,3);set(caster,"learnedSkills",Set.of(9,33,37,44));set(caster,"inventory",RuntimeInventory.fromCatalogCounts(Map.of(40318L,100)));set(caster,"playerLawful",32767);gear(caster,30,0,0);ready(caster,1000);long now=System.nanoTime();npc(pc,now,4);
  int skill=33;byte[] payload=new Protocol.Writer().c(0x14).c((skill-1)/8).c((skill-1)%8).d(pc.playerObjectId()).h(pc.battleX()).h(pc.battleY()).bytes();String output=output(()->call(caster,"useSpell",new Class[]{byte[].class},payload));var t=CombatPoisonAtomic.status(pc);check(CombatPoisonParalysis.curseVisual(t,System.nanoTime())&&CombatPoisonParalysis.poisonVisual(t,System.nanoTime()),"actual native33 admitted with existing NPC poison: "+output);int mp=(int)get(caster,"playerMp");long end=(long)get(t,"paralysisExpiresAtNanos");ready(caster,mp);output(()->call(caster,"useSpell",new Class[]{byte[].class},payload));check((int)get(caster,"playerMp")==mp&&(long)get(t,"paralysisExpiresAtNanos")==end,"native33 same-curse rejection preserves cost and deadline");
  fresh(pc,hub,world);ready(caster,1000);output(()->call(caster,"useSpell",new Class[]{byte[].class},payload));check(npc(pc,System.nanoTime(),4)&&CombatPoisonParalysis.curseVisual(t,System.nanoTime()),"NPC poison admitted after actual native33 without replacing it");
 }
 public static void main(String[] args)throws Exception{
  var config=copy(ServerConfig.load(Path.of(args[0]),"standard"),Map.of("classicWorldMonsterPoisonFixtureRoll",1,"curseParalysisFixturePercentileRoll",1,"battleNaturalHpRegenEnabled",false,"battleNaturalMpRegenEnabled",false));ResourceDatabase.load(config);var root=Path.of(args[1]);Files.createDirectories(root);var state=new GameStateStore(root.resolve("unused"),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
  try(var capture=new CaptureLog(root.resolve("capture"));var hub=new GameHub(config,state,accounts);var f=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME)){
   var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();check(clock.awaitTermination(1,TimeUnit.SECONDS),"clock stopped for explicit boundaries");var fixtures=List.of(f,p,m,o);for(int i=0;i<4;i++){var actor=fixtures.get(i).session;NativeDirectoryRegression.init(fixtures.get(i),"PoisonParalysis"+i,0,config.classicServerNames().get(0));var c=((List<CharacterSummary>)get(actor,"characters")).get(0);set(actor,"characters",List.of(copy(c,Map.of("objectId",0x389e0001L+i,"intelligence",35,"originalIntelligence",35,"wisdom",9,"originalWisdom",9,"armorClass",10))));set(actor,"sourceBaseMagicResistance",new SourceBaseMagicResistance(0,0,0,0,0));set(actor,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());set(actor,"sourceEquipmentMagicStats",SourceEquipmentMagicStats.none());set(actor,"learnedSkills",Set.of(9,33,37,44));ready(actor,1000);}
   FlowRegression.setup(hub,f.session,p.session,m.session,o.session);var caster=f.session;var pc=p.session;set(m.session,"observer",true);set(o.session,"observer",true);
   for(boolean world:new boolean[]{false,true}){for(int i=0;i<2;i++){var actor=fixtures.get(i).session;set(actor,"positionX",world?33089+i:32740+i);set(actor,"positionY",world?32717:32798);if(world){set(actor,"phase",Enum.valueOf((Class)get(actor,"phase").getClass(),"WORLD"));set(actor,"classicWorldMapId",4);set(actor,"classicWorldInstanceId",-1);hub.enterClassicWorld(actor,4,33089+i,32717,0);}}coexist(caster,pc,hub,world,capture);nativeCurse(caster,pc,hub,world);fresh(pc,hub,world);}
   var rules=CombatRegression.current(CombatRules.class);var saved=rules.get(null);try{rules.set(null,null);fresh(pc,hub,true);long now=System.nanoTime();check(npc(pc,now,4),"unloaded legacy NPC install");var t=CombatPoisonAtomic.status(pc);check(child(t)==null&&!t.activateParalysis(now,1000,3000),"unloaded legacy single paralysis slot retained");}finally{rules.set(null,saved);fresh(pc,hub,true);}
  }
  System.out.println("PASS source independent poison paralysis checks="+checks+"; seven PC types/BATTLE/WORLD, poison1/2/4 and ordinary curse in both orders, actual native33/9/37/44, independent20s+45s/curse deadlines, gray palette/action gates, no premature unlock, expiry orders/reset/slot retirement; damage CAS closing callbacks verified separately; full silence/paralysis callback lifecycle pending; no player SQL writes/deployment");
 }
}
